          Color.lerp(textOnDarkAccent, other.textOnDarkAccent, t) ??
          textOnDarkAccent,
      textPrimary: Color.lerp(textPrimary, other.textPrimary, t) ?? textPrimary,
      textSecondary:
          Color.lerp(textSecondary, other.textSecondary, t) ?? textSecondary,
      textTertiary:
          Color.lerp(textTertiary, other.textTertiary, t) ?? textTertiary,
    ),
  };
}

extension FujinColorsContext on BuildContext {
  static const _missingColors = 'FujinColors is missing from the theme';

  FujinColors get colors =>
      Theme.of(this).extension<FujinColors>() ??
      (throw StateError(_missingColors));
}

